:root {
  color-scheme: light;
  --canvas: var(--rhoe-canvas, #eef1ed);
  --surface: var(--rhoe-surface, #fcfdfb);
  --surface-muted: var(--rhoe-surface-muted, #e2e6e1);
  --text: var(--rhoe-text, #191b19);
  --text-secondary: var(--rhoe-text-secondary, #59605b);
  --border: var(--rhoe-border, #d9ddd9);
  --primary: var(--rhoe-primary, #252725);
  --primary-hover: var(--rhoe-primary-hover, #343734);
  --primary-foreground: var(--rhoe-primary-foreground, #f8faf8);
  --success: var(--rhoe-success, #18794e);
  --success-foreground: var(--rhoe-success-foreground, #ffffff);
  --success-surface: var(--rhoe-success-surface, #e7f6ec);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #17653f);
  --warning: var(--rhoe-warning, #946200);
  --warning-foreground: var(--rhoe-warning-foreground, #ffffff);
  --warning-surface: var(--rhoe-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #6b4600);
  --danger: var(--rhoe-danger, #b42318);
  --danger-foreground: var(--rhoe-danger-foreground, #ffffff);
  --danger-surface: var(--rhoe-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #8f1d14);
  --focus: var(--rhoe-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --duration-considered: 480ms;
  --duration-reveal: 600ms;
  --duration-expand: 720ms;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --input-expanded-duration: var(--duration-considered);
  --input-expanded-ease: var(--ease-enter);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--rhoe-canvas, #121412);
    --surface: var(--rhoe-surface, #1a1d1a);
    --surface-muted: var(--rhoe-surface-muted, #232623);
    --text: var(--rhoe-text, #f1f3f0);
    --text-secondary: var(--rhoe-text-secondary, #afb5b0);
    --border: var(--rhoe-border, #373b37);
    --primary: var(--rhoe-primary, #ecefeb);
    --primary-hover: var(--rhoe-primary-hover, #ffffff);
    --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
    --success: var(--rhoe-success, #62c98f);
    --success-foreground: var(--rhoe-success-foreground, #092416);
    --success-surface: var(--rhoe-success-surface, #173526);
    --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
    --warning: var(--rhoe-warning, #e9ad45);
    --warning-foreground: var(--rhoe-warning-foreground, #291900);
    --warning-surface: var(--rhoe-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
    --danger: var(--rhoe-danger, #ff716b);
    --danger-foreground: var(--rhoe-danger-foreground, #260503);
    --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
    --focus: var(--rhoe-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--rhoe-canvas, #121412);
  --surface: var(--rhoe-surface, #1a1d1a);
  --surface-muted: var(--rhoe-surface-muted, #232623);
  --text: var(--rhoe-text, #f1f3f0);
  --text-secondary: var(--rhoe-text-secondary, #afb5b0);
  --border: var(--rhoe-border, #373b37);
  --primary: var(--rhoe-primary, #ecefeb);
  --primary-hover: var(--rhoe-primary-hover, #ffffff);
  --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
  --success: var(--rhoe-success, #62c98f);
  --success-foreground: var(--rhoe-success-foreground, #092416);
  --success-surface: var(--rhoe-success-surface, #173526);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
  --warning: var(--rhoe-warning, #e9ad45);
  --warning-foreground: var(--rhoe-warning-foreground, #291900);
  --warning-surface: var(--rhoe-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
  --danger: var(--rhoe-danger, #ff716b);
  --danger-foreground: var(--rhoe-danger-foreground, #260503);
  --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
  --focus: var(--rhoe-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .rhoe-code-source .shiki,
html[data-theme="dark"] .rhoe-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .rhoe-code-source .shiki,
  html:not([data-theme="light"]) .rhoe-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes rhoe-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes rhoe-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes rhoe-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

@keyframes rhoe-calendar-range-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type CSSProperties,
  type ReactNode,
} from "react";
import "../foundation.css";

export type BadgeVariant = "filled" | "bordered";
export type BadgeTone = "neutral" | "success" | "warning" | "danger";

export interface BadgeProps extends ComponentPropsWithoutRef<"span"> {
  /** Visual treatment for the status label. */
  variant?: BadgeVariant;
  /** Semantic status color. */
  tone?: BadgeTone;
  /** Optional leading icon. */
  icon?: ReactNode;
  /** Visible status or category label. */
  children: ReactNode;
  /** Overrides the label color with any CSS color value. */
  color?: CSSProperties["color"];
  /** Overrides the surface color with any CSS color value. */
  backgroundColor?: CSSProperties["backgroundColor"];
  /** Overrides the outline color for the bordered variant with any CSS color value. */
  borderColor?: CSSProperties["borderColor"];
}

export const Badge = forwardRef<HTMLSpanElement, BadgeProps>(function Badge({
  variant = "filled",
  tone = "neutral",
  icon,
  color,
  backgroundColor,
  borderColor,
  className,
  style,
  children,
  ...props
}, ref) {
  const customColors = {
    ...style,
    "--badge-color": color,
    "--badge-background": backgroundColor,
    "--badge-border": variant === "bordered" ? borderColor : undefined,
  } as CSSProperties;

  return (
    <span
      ref={ref}
      {...props}
      className={[
        "inline-flex min-h-7 items-center justify-center gap-[5px] rounded-full border px-2.5 font-[inherit] text-[11px] font-bold leading-none tracking-[0.01em] align-middle whitespace-nowrap [background:var(--badge-background)] [border-color:var(--badge-border,transparent)] [color:var(--badge-color)]",
        variant === "filled" && "data-[tone=neutral]:[--badge-background:var(--surface-muted)] data-[tone=neutral]:[--badge-color:var(--text-secondary)] data-[tone=success]:[--badge-background:var(--success-surface)] data-[tone=success]:[--badge-color:var(--success-surface-foreground)] data-[tone=warning]:[--badge-background:var(--warning-surface)] data-[tone=warning]:[--badge-color:var(--warning-surface-foreground)] data-[tone=danger]:[--badge-background:var(--danger-surface)] data-[tone=danger]:[--badge-color:var(--danger-surface-foreground)]",
        variant === "bordered" && "data-[tone=neutral]:[--badge-background:color-mix(in_srgb,var(--surface-muted)_58%,transparent)] data-[tone=neutral]:[--badge-border:color-mix(in_srgb,var(--text-secondary)_46%,transparent)] data-[tone=neutral]:[--badge-color:var(--text-secondary)] data-[tone=success]:[--badge-background:color-mix(in_srgb,var(--success-surface)_68%,transparent)] data-[tone=success]:[--badge-border:color-mix(in_srgb,var(--success-surface-foreground)_52%,transparent)] data-[tone=success]:[--badge-color:var(--success-surface-foreground)] data-[tone=warning]:[--badge-background:color-mix(in_srgb,var(--warning-surface)_68%,transparent)] data-[tone=warning]:[--badge-border:color-mix(in_srgb,var(--warning-surface-foreground)_52%,transparent)] data-[tone=warning]:[--badge-color:var(--warning-surface-foreground)] data-[tone=danger]:[--badge-background:color-mix(in_srgb,var(--danger-surface)_68%,transparent)] data-[tone=danger]:[--badge-border:color-mix(in_srgb,var(--danger-surface-foreground)_52%,transparent)] data-[tone=danger]:[--badge-color:var(--danger-surface-foreground)]",
        className,
      ].filter(Boolean).join(" ")}
      data-tone={tone}
      style={customColors}
    >
      {icon ? <span className="grid shrink-0 place-items-center [&>svg]:size-[13px]" aria-hidden="true">{icon}</span> : null}
      {children}
    </span>
  );
});
